fn save_logs(capture: &Capture, output: &std::process::Output) -> Result<(), String> {
    std::fs::write(capture.directory.join("cargo.jsonl"), &output.stdout)
        .map_err(|e| e.to_string())?;
    std::fs::write(capture.directory.join("cargo.stderr"), &output.stderr)
        .map_err(|e| e.to_string())
}

/// Picks the line a suppression comment may live on: the nearest line above
/// `fn_line_index` (0-based) that is not an attribute or doc comment.
pub fn preceding_comment_line(lines: &[&str], fn_line_index: usize) -> String {
    lines[..fn_line_index.min(lines.len())]
        .iter()
        .rev()
        .map(|line| line.trim())
        .find(|line| !line.starts_with("#[") && !line.starts_with("///"))
        .unwrap_or("")
        .to_string()
}

fn collect(mut reader: impl Read) -> io::Result<Vec<u8>> {
    let mut bytes = Vec::new();
    reader.read_to_end(&mut bytes)?;

    Ok(bytes)
}

fn emit(bytes: &[u8]) {
    let mut stderr = io::stderr().lock();
    let _ = stderr.write_all(bytes);
    let _ = stderr.flush();
}

fn tee(reader: impl Read) -> io::Result<Vec<u8>> {
    collect(StderrTee(reader))
}
